local function T(key, ...)
    if not key then return "" end
    local lang = L[Config.Language or "en"] or L.en
    local s = lang[key] or L.en[key] or key
    if type(s) ~= "string" then return tostring(s) end
    if select("#", ...) > 0 and s:find("%%") then
        local ok, res = pcall(string.format, s, ...)
        if ok then return res end
    end
    return s
end

local function tPlaceholder(inst, key)
    inst:SetAttribute("_tPlaceholder", key)
    inst.PlaceholderText = T(key)
    return inst
end

-- ══════════════════════════════════════════════════════════════
-- IMAGE / ASSET HELPERS
-- ══════════════════════════════════════════════════════════════
local function sanitizeAssetSource(str)
    if not str then return nil end
    if type(str) == "number" then
        if str > 0 and str == math.floor(str) then
            return "rbxassetid://" .. tostring(str)
        end
        return nil
    end
    str = tostring(str)
    str = str:gsub("%s+", "")
    if str == "" then return nil end
    if str:match("^rbxasset://") then return str end
    if str:match("^rbxassetid://%d+$") then return str end
    local num = tonumber(str)
    if num and num > 0 and num == math.floor(num) then
        return "rbxassetid://" .. tostring(math.floor(num))
    end
    local id = str:match("rbxassetid://(%d+)")
        or str:match("[?&]id=(%d+)")
        or str:match("(%d+)")
    if id and tonumber(id) and tonumber(id) > 0 then
        return "rbxassetid://" .. id
    end
    return nil
end

-- ══════════════════════════════════════════════════════════════
-- FPS + PING
-- ══════════════════════════════════════════════════════════════
local currentFPS = 60
do
    local fc, ft = 0, 0
    RunService.RenderStepped:Connect(function(dt)
        fc = fc + 1; ft = ft + dt
        if ft >= 0.5 then
            currentFPS = math.floor(fc / ft + 0.5)
            fc, ft = 0, 0
        end
    end)
end
local function getPing()
    local ok, p = pcall(function() return math.floor(LocalPlayer:GetNetworkPing() * 1000 + 0.5) end)
    return ok and p or 0
end

