-- WINDOW
-- ══════════════════════════════════════════════════════════════
local function createWindow(opts)
    local window
    local parent = getSafeParent()
    local gui = new("ScreenGui", {Name = "airhubUI_" .. tostring(math.random(1000,9999)),
