    addBrackets(main, 14, 2, Theme.Accent)

    local animScale = Instance.new("UIScale"); animScale.Scale = 1; animScale.Parent = main

    local titlebar = new("Frame", {BorderSizePixel = 0, Size = UDim2.new(1,0,0,40), ZIndex = 2,
