    Callback = function(v) Window:Configure({MenuAnimSpeed = v}) end, Tooltip = "tt_menu_open"})
secAnim:AddSlider({Name = "lbl_menu_close", Value = Config.MenuCloseAnim, Min = 0.1, Max = 1.0, Decimals = 2,
