            t.Center   = true
            t.Outline  = true
            t.Position = workspace.CurrentCamera.ViewportSize / 2
            task.delay(2, function() t:Remove() end)
        end)

        if type(_origOnUnload) == "function" then
            pcall(_origOnUnload, win)
        end
    end
else
