local PHYLLOTAXIS = {}
do
    local GA = math.pi * (3 - math.sqrt(5))
    local N = 32
    for i = 1, N do
        local r = math.sqrt(i / N)
        local a = i * GA
        PHYLLOTAXIS[i] = { r * math.cos(a), r * math.sin(a) }
    end
end

