            Enabled = false,
            Mode = "Default",
            Method = "CFrame",
            DesyncFrom = "Player", -- NEW
            X = 5, Y = 5, Z = 5,
            Random = false,
            UpdateInterval = 0.05,
            OldPosDelayEnabled = true,
            OldPosDelay = 0.5,
            VoidDepth = -1000,
            InPlayerOffset = 2,
            RefreshOnShot = false,
            RandomRotate = false,
            Visualize = false,
        }
        AB.Settings = {
            Enabled        = false,
            Mode           = "Speed",
            Preset         = "None",
            CustomId       = "",
            Speed          = 1,
            RandomInterval = 0.1,
            ApplyToServer  = true,
        }
        pcall(StopAnimationBreaker)

        AntiAim.Internal = {
            BodyLastUpdate = 0, BodyJitterTime = 0, BodyJitterOffset = 0,
            BodyGyro = nil, AlignOrientation = nil,
