        AmbientColor            = Color3.fromRGB(70, 70, 70),
        OutdoorAmbientColor     = Color3.fromRGB(128, 128, 128),
        EnvironmentDiffuseScale = 0.5,
        EnvironmentSpecularScale= 0.5,
        ShadowSoftness          = 0.2,
        Technology              = "Future",

        -- Camera FOV
        CameraFOVEnabled = false,
        CameraFOVValue   = 70,

        -- Custom Fog
        CustomFog  = false,
        FogStart   = 0,
        FogEnd     = 100000,
        FogColor   = Color3.fromRGB(192, 192, 192),

        -- Atmosphere
        AtmosphereEnabled = false,
        AtmosphereDensity = 0.30,
        AtmosphereOffset  = 0,
        AtmosphereGlare   = 0,
        AtmosphereHaze    = 1.5,
        AtmosphereColor   = Color3.fromRGB(199, 199, 199),
        AtmosphereDecay   = Color3.fromRGB(106, 112, 125),

        -- Bloom
        BloomEnabled   = false,
        BloomIntensity = 0.8,
        BloomSize      = 24,
        BloomThreshold = 2,

        -- Color Correction
        CCEnabled    = false,
        CCBrightness = 0,
        CCContrast   = 0.10,
        CCSaturation = 0.10,
        CCTintColor  = Color3.fromRGB(255, 255, 255),

        -- Depth of Field
        DOFEnabled       = false,
        DOFFarIntensity  = 0.1,
        DOFFocusDistance = 20,
        DOFInFocusRadius = 30,
        DOFNearIntensity = 0.5,

        -- Sun Rays
        SunRaysEnabled   = false,
        SunRaysIntensity = 0.1,
        SunRaysSpread    = 1,

        -- Blur
        BlurEnabled = false,
        BlurSize    = 0,

        -- Sky
        CustomSky         = false,
        SkyStarCount      = 3000,
        SkySunAngularSize = 21,
        SkyMoonAngularSize= 11,
    },
    Internal = {
        Original = {
            Lighting   = OrigLighting,
            Atmosphere = OrigAtmosphere,
            Sky        = OrigSky,
            SkyProps   = OrigSkyProps,
            FX         = OrigFX,
            CameraFOV  = nil,  -- lazily captured on first Apply
        },
