--// ---------------------------------------------------------------------------
local function ApplyCameraFOV()
    local cam = workspace.CurrentCamera
    if not cam then return end
    if World.Internal.Original.CameraFOV == nil then
        World.Internal.Original.CameraFOV = cam.FieldOfView or 70
    end
