    local snap = World.Internal.Original.FX.Bloom
    if snap and snap.instance == fx then
        for k, v in pairs(snap.properties) do safeSet(fx, k, v) end
    else
        safeSet(fx, "Enabled", false)
    end
end

local function ApplyCC()
