end

local function Preset_Clean()
    local S = World.Settings
    S.CustomLighting = false
    S.CustomFog = false
    S.AtmosphereEnabled = false
    S.CustomSky = false
    S.BloomEnabled = false
    S.CCEnabled = false
    S.DOFEnabled = false
    S.SunRaysEnabled = false
    S.BlurEnabled = false

    S.Fullbright = true
    S.RemoveFog = true
    S.NoShadows = true

    ApplyLook()
end

