    { name = "07_exploits.lua", extra = false, src = [[
--// ============================================================================
--// AirHub — 07_exploits.lua (airhubUI build, v3 — FakeLag FIX)
--// Exploits tab: Character, Combat, World, Server, Network, RakNet, Player.
--//
--// v3 CHANGES (FakeLag rewrite — no more "everything broken"):
--//   • FakeLagMode = "Movement" default (safe) — only delays movement-related remotes
--//   • Hardcoded blacklist: Chat, Buy, Shop, Report, AntiCheat, Kick, Ban, etc.
--//   • Per-remote rate-limit: calls > 20ms apart pass through immediately
--   • Max Queue + gradual flush (5ms between packets) — no server kick on unload
--   • Auto-enable from Backtrack removed (was breaking everything)
--   • OnlyAlive flushes queue safely on death
--   • Custom mode with whitelist for advanced users
--// All prior fixes preserved: Anti-Void reset, Anti-Fling thresholds,
--// immediate HitboxExpander, SeeThroughWalls transparency skip,
--// Anti-Teleport, InstantPrompt, Invisible (local only), RU loc + tooltips.
--// ============================================================================
local H = getgenv().AirHub
if not H or not H._CoreLoaded then warn("[AirHub] 07_exploits: core not loaded"); return end
if H.Exploits and H.Exploits._Loaded then return end

local Util             = H.Util
local Players          = Util.Players
local RunService       = Util.RunService
local UserInputService = Util.UserInputService
local LocalPlayer      = Util.LocalPlayer

local TeleportService  = game:GetService("TeleportService")
local HttpService      = game:GetService("HttpService")
local VirtualUser      = game:GetService("VirtualUser")
local Lighting         = game:GetService("Lighting")

local function getExec(name)
    local f = rawget(_G, name)
    if type(f) == "function" then return f end
    if type(getgenv) == "function" then
        local ok, env = pcall(getgenv)
        if ok and type(env) == "table" then
            f = rawget(env, name)
            if type(f) == "function" then return f end
        end
    end
    return nil
end

--// ---------------------------------------------------------------------------
--// 1) Schema
--// ---------------------------------------------------------------------------
H.Exploits = H.Exploits or {}
local Ex = H.Exploits
Ex._Loaded = true

Ex.Settings = Ex.Settings or {
    AntiAFK          = false,
    AntiFling        = false,
    AntiVoid         = false,
    AntiRagdoll      = false,
    InfiniteJump     = false,
    AntiTeleport     = false,
    AntiTeleportMode = "Restore",
    AntiTeleportMax  = 100,

    SeeThroughWalls  = false,
    Fullbright       = false,
    FullbrightBrightness = 2,
    RemoveFog        = false,
    RemoveSkybox     = false,

    HitboxExpander   = false,
    HitboxSize       = 3,
    HitboxPart       = "Head",
    HitboxTeamCheck  = false,

    BacktrackEnabled     = false,
    BacktrackTime        = 150,
    BacktrackVisualize   = true,
    BacktrackGhostStyle  = "Clone",
