--// ---------------------------------------------------------------------------
--// 2) Real init
--// ---------------------------------------------------------------------------
local okInit, errInit = pcall(function()

    local StartFakeLag, StopFakeLag

    local function safeDisconnect(conn)
        if conn then pcall(function() conn:Disconnect() end) end
    end

    local function safeKeys(t)
        local keys = {}
        for k in pairs(t) do keys[#keys + 1] = k end
        return keys
    end

    local function isCharacterPart(part)
        if not part or not part.Parent then return false end
        if Players:GetPlayerFromCharacter(part.Parent) then return true end
        if part.Parent:FindFirstChildOfClass("Humanoid") then return true end
        return false
    end

    local function IsLocalPlayerAlive()
        local char = LocalPlayer.Character
        if not char then return false end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return false end
        if not char:FindFirstChild("HumanoidRootPart") then return false end
        return true
    end

    local function isAirHubInternal(obj)
        local ok, v = pcall(function() return obj:GetAttribute("AirHubInternal") end)
        return ok and v == true
    end

    local function IsEnemyByAimbot(plr)
        if not plr or plr == LocalPlayer then return false end
        local A = H.Aimbot
        if not A or not A.Settings or not A.Settings.TeamCheck then return true end
        local tc = A.Settings.TeamCheck
        if not tc.Enabled then return true end
        local lt, tt = LocalPlayer.Team, plr.Team
        local mode = tc.Mode or "Enemies"
        if mode == "All" then return true end
        if mode == "Enemies" then
            if lt and tt and lt == tt then return false end
            if (not lt or not tt) and not tc.TreatNeutralAsEnemy then return false end
            return true
        elseif mode == "Allies" then
            return (lt ~= nil and tt ~= nil and lt == tt) and true or false
        elseif mode == "IgnoreNeutrals" then
            if not lt or not tt then return false end
            return lt ~= tt
        end
        return true
    end

    local function GetLocalHRP()
        local char = LocalPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end

    --// =======================================================================
    --// CHARACTER
    --// =======================================================================
    local function StartAntiAFK()
        if Ex.Internal.Conns.afk then return end
        Ex.Internal.Conns.afk = LocalPlayer.Idled:Connect(function()
            if H.ShuttingDown then return end
            pcall(function()
                VirtualUser:CaptureController()
                VirtualUser:ClickButton2(Vector2.new())
            end)
        end)
    end
    local function StopAntiAFK()
        safeDisconnect(Ex.Internal.Conns.afk)
        Ex.Internal.Conns.afk = nil
    end

    local FLING_SPIKE     = 500
    local FLING_SUSTAINED = 200
    local FLING_WINDOW    = 3
    local function StartAntiFling()
        if Ex.Internal.Conns.fling then return end
        local history = {}
        Ex.Internal.Conns.fling = RunService.Heartbeat:Connect(function()
            if H.ShuttingDown then return end
            local char = LocalPlayer.Character
            if not char then history = {}; return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then return end
            local vel = hrp.AssemblyLinearVelocity or hrp.Velocity
            local mag = vel.Magnitude
            history[#history + 1] = mag
            if #history > FLING_WINDOW then table.remove(history, 1) end
            local spike = mag > FLING_SPIKE
            local sustained = false
            if #history >= FLING_WINDOW then
                sustained = true
                for i = 1, #history do
                    if history[i] < FLING_SUSTAINED then sustained = false break end
                end
            end
            if spike or sustained then
                pcall(function() hrp.AssemblyLinearVelocity = Vector3.new() end)
                pcall(function() hrp.Velocity = Vector3.new() end)
                pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                history = {}
            end
        end)
    end
    local function StopAntiFling()
        safeDisconnect(Ex.Internal.Conns.fling)
        Ex.Internal.Conns.fling = nil
    end

    local VOID_Y = -100
    local SAFE_BUFFER = 5
    local function StartAntiVoid()
        if Ex.Internal.Conns.void then return end
        if not Ex.Internal.Conns.voidChar then
            Ex.Internal.Conns.voidChar = LocalPlayer.CharacterAdded:Connect(function()
                Ex.Internal.LastSafeCFrame = nil
            end)
        end
        local safeBuf = {}
        Ex.Internal.Conns.void = RunService.Heartbeat:Connect(function()
            if H.ShuttingDown then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            if hrp.Position.Y > 5 then
                safeBuf[#safeBuf + 1] = hrp.CFrame
                if #safeBuf > SAFE_BUFFER then table.remove(safeBuf, 1) end
                Ex.Internal.LastSafeCFrame = safeBuf[#safeBuf]
            end
            if hrp.Position.Y < VOID_Y and Ex.Internal.LastSafeCFrame then
                pcall(function() char:PivotTo(Ex.Internal.LastSafeCFrame) end)
                pcall(function() hrp.AssemblyLinearVelocity = Vector3.new() end)
                safeBuf = {}
                Ex.Internal.LastSafeCFrame = nil
            end
        end)
    end
    local function StopAntiVoid()
        safeDisconnect(Ex.Internal.Conns.void)
        Ex.Internal.Conns.void = nil
        safeDisconnect(Ex.Internal.Conns.voidChar)
        Ex.Internal.Conns.voidChar = nil
        Ex.Internal.LastSafeCFrame = nil
    end

    local function StartAntiTeleport()
        if Ex.Internal.Conns.antitp then return end
        Ex.Internal.AntiTeleportLastCF = nil
        Ex.Internal.Conns.antitpChar = LocalPlayer.CharacterAdded:Connect(function()
            Ex.Internal.AntiTeleportLastCF = nil
        end)
        Ex.Internal.Conns.antitp = RunService.Heartbeat:Connect(function()
            if H.ShuttingDown or not Ex.Settings.AntiTeleport then return end
            local hrp = GetLocalHRP()
            if not hrp then
                Ex.Internal.AntiTeleportLastCF = nil
                return
            end
            local curCF = hrp.CFrame
            local prevCF = Ex.Internal.AntiTeleportLastCF
            if prevCF then
                local maxJump = tonumber(Ex.Settings.AntiTeleportMax) or 100
                local delta = (curCF.Position - prevCF.Position).Magnitude
                if delta > maxJump then
                    local mode = Ex.Settings.AntiTeleportMode or "Restore"
                    if mode == "Restore" or mode == "Block" then
                        pcall(function() hrp.CFrame = prevCF end)
                        Ex.Internal.AntiTeleportLastCF = hrp.CFrame
                        return
                    end
                end
            end
            Ex.Internal.AntiTeleportLastCF = curCF
        end)
    end
    local function StopAntiTeleport()
        safeDisconnect(Ex.Internal.Conns.antitp)
        Ex.Internal.Conns.antitp = nil
        safeDisconnect(Ex.Internal.Conns.antitpChar)
        Ex.Internal.Conns.antitpChar = nil
        Ex.Internal.AntiTeleportLastCF = nil
    end

    local function StartAntiRagdoll()
        if Ex.Internal.Conns.ragdoll then return end
        Ex.Internal.Conns.ragdoll = RunService.Heartbeat:Connect(function()
            if H.ShuttingDown then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            if hum.PlatformStand then hum.PlatformStand = false end
            local st = hum:GetState()
            if st == Enum.HumanoidStateType.Physics
               or st == Enum.HumanoidStateType.FallingDown
               or st == Enum.HumanoidStateType.Ragdoll then
                pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
            end
        end)
    end
    local function StopAntiRagdoll()
        safeDisconnect(Ex.Internal.Conns.ragdoll)
        Ex.Internal.Conns.ragdoll = nil
    end

    local function StartInfiniteJump()
        if Ex.Internal.Conns.jump then return end
        Ex.Internal.Conns.jump = UserInputService.JumpRequest:Connect(function()
            if H.ShuttingDown then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hum then return end
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
            if hrp then
                local v = hrp.AssemblyLinearVelocity
                if v.Y < 30 then
                    pcall(function()
                        hrp.AssemblyLinearVelocity = Vector3.new(v.X, math.max(v.Y, 30), v.Z)
                    end)
                end
            end
        end)
    end
    local function StopInfiniteJump()
        safeDisconnect(Ex.Internal.Conns.jump)
        Ex.Internal.Conns.jump = nil
    end

    local function ApplyPrompt(prompt)
        if not prompt or not prompt:IsA("ProximityPrompt") then return end
        if not Ex.Internal.PromptOriginals[prompt] then
            Ex.Internal.PromptOriginals[prompt] = {
                HoldDuration = prompt.HoldDuration,
                MaxActivationDistance = prompt.MaxActivationDistance,
            }
        end
        pcall(function()
            prompt.HoldDuration = 0
            prompt.MaxActivationDistance = 1e9
        end)
    end
    local function StartInstantPrompt()
        for _, obj in ipairs(workspace:GetDescendants()) do
            ApplyPrompt(obj)
        end
        if Ex.Internal.Conns.prompt then return end
        Ex.Internal.Conns.prompt = workspace.DescendantAdded:Connect(function(obj)
            if H.ShuttingDown or not Ex.Settings.InstantPrompt then return end
            ApplyPrompt(obj)
        end)
    end
    local function StopInstantPrompt()
        safeDisconnect(Ex.Internal.Conns.prompt)
        Ex.Internal.Conns.prompt = nil
        for prompt, orig in pairs(Ex.Internal.PromptOriginals) do
            if prompt and prompt.Parent then
                pcall(function()
                    prompt.HoldDuration = orig.HoldDuration
                    prompt.MaxActivationDistance = orig.MaxActivationDistance
                end)
            end
        end
        Ex.Internal.PromptOriginals = {}
    end

    local function ApplyInvisibleToChar()
        local char = LocalPlayer.Character
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then
                if Ex.Internal.InvisibleOriginals[part] == nil then
                    Ex.Internal.InvisibleOriginals[part] = part.LocalTransparencyModifier
                end
                pcall(function() part.LocalTransparencyModifier = 1 end)
            end
        end
    end
    local function StartInvisible()
        ApplyInvisibleToChar()
        if not Ex.Internal.Conns.invisibleChar then
            Ex.Internal.Conns.invisibleChar = LocalPlayer.CharacterAdded:Connect(function()
                task.wait(0.1)
                if H.ShuttingDown or not Ex.Settings.Invisible then return end
                ApplyInvisibleToChar()
            end)
        end
        if not Ex.Internal.Conns.invisibleLoop then
            Ex.Internal.Conns.invisibleLoop = task.spawn(function()
                while not H.ShuttingDown and Ex.Settings.Invisible do
                    ApplyInvisibleToChar()
                    task.wait(0.25)
                end
            end)
        end
    end
    local function StopInvisible()
        safeDisconnect(Ex.Internal.Conns.invisibleChar)
        Ex.Internal.Conns.invisibleChar = nil
        Ex.Internal.Conns.invisibleLoop = nil
        for part, orig in pairs(Ex.Internal.InvisibleOriginals) do
            if part and part.Parent then
                pcall(function() part.LocalTransparencyModifier = orig or 0 end)
            end
        end
        Ex.Internal.InvisibleOriginals = {}
    end

    --// =======================================================================
    --// SILENT ACCEPT (unchanged — kept as-is, works fine)
    --// =======================================================================
    local SILENT_ACCEPT_MIN_THRESHOLD = 0.5
    local SILENT_ACCEPT_MISS_LIMIT    = 1

    local function ApplySilentAcceptRestore(hrp, safeCF, mode)
        if mode == "Nothing" or mode == "CFrame" then
            pcall(function() hrp.CFrame = safeCF end)
        elseif mode == "Position" then
            pcall(function() hrp.Position = safeCF.Position end)
        end
    end

    local function ResetSilentAcceptBaseline(hrp)
        Ex.Internal.SilentAcceptLastHrp    = hrp
        Ex.Internal.SilentAcceptSafeCF     = hrp and hrp.CFrame or nil
        Ex.Internal.SilentAcceptSafeTime   = tick()
        Ex.Internal.SilentAcceptSafeVel    = hrp and (hrp.AssemblyLinearVelocity or hrp.Velocity) or nil
        Ex.Internal.SilentAcceptMissFrames = 0
    end

    local function StartSilentAccept()
        if Ex.Internal.SilentAcceptConn then return end
        ResetSilentAcceptBaseline(nil)
        Ex.Internal.SilentAcceptConn = RunService.Heartbeat:Connect(function()
            if H.ShuttingDown or not Ex.Settings.SilentAccept then return end
            local hrp = GetLocalHRP()
            if not hrp then
                if Ex.Internal.SilentAcceptLastHrp ~= nil then
                    ResetSilentAcceptBaseline(nil)
                end
                return
            end
            if Ex.Internal.SilentAcceptLastHrp ~= hrp then
                ResetSilentAcceptBaseline(hrp); return
            end
            if Ex.Internal.SilentAcceptRestoring then
                Ex.Internal.SilentAcceptRestoring = false
                ResetSilentAcceptBaseline(hrp); return
            end
            local safeCF   = Ex.Internal.SilentAcceptSafeCF
            local safeTime = Ex.Internal.SilentAcceptSafeTime
            local now      = tick()
            if safeCF and safeTime then
                local dt = now - safeTime
                if dt > 0 and dt < 0.5 then
                    local current = hrp.CFrame
                    local actualDelta = (current.Position - safeCF.Position).Magnitude
                    local vel = hrp.AssemblyLinearVelocity or hrp.Velocity
                    local speed = (vel and vel.Magnitude) or 0
                    local prevVel = Ex.Internal.SilentAcceptSafeVel
                    local prevSpeed = (prevVel and prevVel.Magnitude) or 0
                    local avgSpeed = (speed + prevSpeed) * 0.5
                    local expected = avgSpeed * dt + 0.75
                    local threshold = math.max(
                        SILENT_ACCEPT_MIN_THRESHOLD,
                        tonumber(Ex.Settings.SilentAcceptThreshold) or 3
                    )
                    if actualDelta > threshold and actualDelta > expected * 2 then
                        Ex.Internal.SilentAcceptMissFrames = Ex.Internal.SilentAcceptMissFrames + 1
                        if Ex.Internal.SilentAcceptMissFrames >= SILENT_ACCEPT_MISS_LIMIT then
                            local mode = Ex.Settings.SilentAcceptMode or "CFrame"
                            Ex.Internal.SilentAcceptRestoring = true
                            ApplySilentAcceptRestore(hrp, safeCF, mode)
                            local restored = GetLocalHRP()
                            if restored then ResetSilentAcceptBaseline(restored)
                            else ResetSilentAcceptBaseline(nil) end
                            return
                        end
                    else
                        Ex.Internal.SilentAcceptMissFrames = 0
                    end
                end
            end
            Ex.Internal.SilentAcceptSafeCF   = hrp.CFrame
            Ex.Internal.SilentAcceptSafeTime = now
            Ex.Internal.SilentAcceptSafeVel  = hrp.AssemblyLinearVelocity or hrp.Velocity
        end)
    end

    local function StopSilentAccept()
        safeDisconnect(Ex.Internal.SilentAcceptConn)
        Ex.Internal.SilentAcceptConn = nil
        Ex.Internal.SilentAcceptSafeCF     = nil
        Ex.Internal.SilentAcceptSafeTime   = nil
        Ex.Internal.SilentAcceptSafeVel    = nil
        Ex.Internal.SilentAcceptRestoring  = false
        Ex.Internal.SilentAcceptLastHrp    = nil
        Ex.Internal.SilentAcceptMissFrames = 0
    end

    --// =======================================================================
    --// VELOCITY SPOOF (unchanged — works)
    --// =======================================================================
    local function BuildVelocitySpoofVector()
        local mode = Ex.Settings.VelocitySpoofMode or "Static"
        if mode == "Zero" then
            return Vector3.new(0, 0, 0)
        elseif mode == "Random" then
            local t = tick()
            if t - (Ex.Internal.VelocitySpoofLastTime or 0) > 0.1 then
                Ex.Internal.VelocitySpoofLastTime = t
                Ex.Internal.VelocitySpoofLastVec = Vector3.new(
                    (math.random() * 2 - 1) * (Ex.Settings.VelocitySpoofX or 0),
                    (math.random() * 2 - 1) * (Ex.Settings.VelocitySpoofY or 0),
                    (math.random() * 2 - 1) * (Ex.Settings.VelocitySpoofZ or 0)
                )
            end
            return Ex.Internal.VelocitySpoofLastVec or Vector3.new(0, 0, 0)
        end
        return Vector3.new(
            Ex.Settings.VelocitySpoofX or 0,
            Ex.Settings.VelocitySpoofY or 0,
            Ex.Settings.VelocitySpoofZ or 0
        )
    end

    local function StartVelocitySpoof()
        if Ex.Internal.VelocitySpoofHooked then return end
        local hookf  = getExec("hookmetamethod")
        local newc   = getExec("newcclosure")
        local checkC = getExec("checkcaller")
        if not hookf or not newc then
            warn("[AirHub] VelocitySpoof: executor lacks hookmetamethod/newcclosure")
            return
        end
        local rawIndex = getrawmetatable and getrawmetatable(game) or nil
        local realIndex = rawIndex and rawIndex.__index or nil
        if type(realIndex) ~= "function" then
            warn("[AirHub] VelocitySpoof: cannot capture __index")
            return
        end
        Ex.Internal.VelocitySpoofOriginal = realIndex
        local hooked = newc(function(self, key)
            if H.ShuttingDown then return realIndex(self, key) end
            if Ex.Internal.VelocitySpoofActive
               and (key == "Velocity" or key == "AssemblyLinearVelocity") then
                if (not checkC) or (not checkC()) then
                    local hrp = GetLocalHRP()
                    if hrp and self == hrp then
                        return BuildVelocitySpoofVector()
                    end
                end
            end
            return realIndex(self, key)
        end)
        local ok = pcall(function() hookf(game, "__index", hooked) end)
        if not ok then
            warn("[AirHub] VelocitySpoof: hookmetamethod failed")
            Ex.Internal.VelocitySpoofOriginal = nil
            return
        end
        Ex.Internal.VelocitySpoofHooked = true
        Ex.Internal.VelocitySpoofActive = true
    end

    local function StopVelocitySpoof()
        if not Ex.Internal.VelocitySpoofHooked then return end
        Ex.Internal.VelocitySpoofActive = false
        local hookf = getExec("hookmetamethod")
        if hookf and Ex.Internal.VelocitySpoofOriginal then
            pcall(function() hookf(game, "__index", Ex.Internal.VelocitySpoofOriginal) end)
        end
        Ex.Internal.VelocitySpoofHooked   = false
        Ex.Internal.VelocitySpoofOriginal = nil
        Ex.Internal.VelocitySpoofLastVec  = nil
        Ex.Internal.VelocitySpoofLastTime = 0
    end

    --// =======================================================================
    --// HITBOX EXPANDER (unchanged — works, applies immediately)
    --// =======================================================================
    local HITBOX_PART_CHAIN = {
        Head             = { "Head" },
        Torso            = { "Torso", "UpperTorso", "LowerTorso" },
        HumanoidRootPart = { "HumanoidRootPart" },
    }

    local function GetHitboxPart(character)
        local chain = HITBOX_PART_CHAIN[Ex.Settings.HitboxPart]
        if not chain then return nil end
        for _, name in ipairs(chain) do
            local p = character:FindFirstChild(name)
            if p and p:IsA("BasePart") then return p end
        end
        return nil
    end

    local RestoreHitboxForPlayer

    local function AttachHitboxListener(player, part)
        if Ex.Internal.HitboxListeners[part] then return end
        local conn = part:GetPropertyChangedSignal("Size"):Connect(function()
            if H.ShuttingDown then return end
            if Ex.Internal.HitboxWriting[part] then return end
            if not Ex.Settings.HitboxExpander then return end
            if not part.Parent then return end
            if Ex.Internal.HitboxApplied[player] ~= part then return end
            if Ex.Settings.HitboxTeamCheck and not IsEnemyByAimbot(player) then
                task.defer(function() RestoreHitboxForPlayer(player) end)
                return
            end
            local s = Ex.Settings.HitboxSize
            local want = Vector3.new(s, s, s)
            if part.Size ~= want then
                Ex.Internal.HitboxWriting[part] = true
                pcall(function() part.Size = want end)
                Ex.Internal.HitboxWriting[part] = nil
            end
        end)
        Ex.Internal.HitboxListeners[part] = conn
    end

    local function DetachHitboxListener(part)
        local conn = Ex.Internal.HitboxListeners[part]
        if conn then
            safeDisconnect(conn)
            Ex.Internal.HitboxListeners[part] = nil
        end
    end

    RestoreHitboxForPlayer = function(player)
        local part = Ex.Internal.HitboxApplied[player]
        if not part then return end
        local orig = Ex.Internal.HitboxOriginal[part]
        if orig and part.Parent then
            pcall(function() part.Size = orig end)
        end
        Ex.Internal.HitboxOriginal[part] = nil
        Ex.Internal.HitboxWriting[part]  = nil
        DetachHitboxListener(part)
        Ex.Internal.HitboxApplied[player] = nil
    end

    local function ApplyHitboxToPlayer(player)
        if player == LocalPlayer then return end
        if Ex.Settings.HitboxTeamCheck and not IsEnemyByAimbot(player) then
            RestoreHitboxForPlayer(player); return
        end
        local char = player.Character
        if not char then RestoreHitboxForPlayer(player); return end
        local part = GetHitboxPart(char)
        if not part then RestoreHitboxForPlayer(player); return end
        local prevPart = Ex.Internal.HitboxApplied[player]
        if prevPart and prevPart ~= part then
            local orig = Ex.Internal.HitboxOriginal[prevPart]
            if orig and prevPart.Parent then
                pcall(function() prevPart.Size = orig end)
            end
            Ex.Internal.HitboxOriginal[prevPart] = nil
            Ex.Internal.HitboxWriting[prevPart]  = nil
            DetachHitboxListener(prevPart)
            Ex.Internal.HitboxApplied[player] = nil
        end
        if not Ex.Internal.HitboxOriginal[part] then
            Ex.Internal.HitboxOriginal[part] = part.Size
        end
        local s = Ex.Settings.HitboxSize
        local newSize = Vector3.new(s, s, s)
        if part.Size ~= newSize then
            Ex.Internal.HitboxWriting[part] = true
            pcall(function() part.Size = newSize end)
            Ex.Internal.HitboxWriting[part] = nil
        end
        Ex.Internal.HitboxApplied[player] = part
        AttachHitboxListener(player, part)
    end

    local function StartHitboxExpander()
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl ~= LocalPlayer then
                if Ex.Settings.HitboxTeamCheck and not IsEnemyByAimbot(pl) then
                    RestoreHitboxForPlayer(pl)
                else
                    ApplyHitboxToPlayer(pl)
                end
            end
        end
        if not Ex.Internal.Conns.hitboxStep then
            Ex.Internal.Conns.hitboxStep = RunService.Stepped:Connect(function()
                if H.ShuttingDown or not Ex.Settings.HitboxExpander then return end
                local s = Ex.Settings.HitboxSize
                local want = Vector3.new(s, s, s)
                for _, pl in ipairs(Players:GetPlayers()) do
                    if pl ~= LocalPlayer then
                        if Ex.Settings.HitboxTeamCheck and not IsEnemyByAimbot(pl) then
                            if Ex.Internal.HitboxApplied[pl] then
                                RestoreHitboxForPlayer(pl)
                            end
                        else
                            local part = Ex.Internal.HitboxApplied[pl]
                            if part and part.Parent and part.Size ~= want then
                                Ex.Internal.HitboxWriting[part] = true
                                pcall(function() part.Size = want end)
                                Ex.Internal.HitboxWriting[part] = nil
                            end
                        end
                    end
                end
            end)
        end
        if not Ex.Internal.HitboxDiscoverRunning then
            Ex.Internal.HitboxDiscoverRunning = true
            task.spawn(function()
                while Ex.Internal.HitboxDiscoverRunning and not H.ShuttingDown do
                    if Ex.Settings.HitboxExpander then
                        for _, pl in ipairs(Players:GetPlayers()) do
                            if pl ~= LocalPlayer then
                                if Ex.Settings.HitboxTeamCheck and not IsEnemyByAimbot(pl) then
                                    if Ex.Internal.HitboxApplied[pl] then
                                        RestoreHitboxForPlayer(pl)
                                    end
                                else
                                    local applied = Ex.Internal.HitboxApplied[pl]
                                    local char = pl.Character
                                    if not applied or not applied.Parent
                                       or not char or applied.Parent ~= char then
                                        ApplyHitboxToPlayer(pl)
                                    end
                                end
                            end
                        end
                        for _, pl in ipairs(safeKeys(Ex.Internal.HitboxApplied)) do
                            if not pl.Parent or not pl.Character then
                                RestoreHitboxForPlayer(pl)
                            end
                        end
                    end
                    task.wait(0.5)
                end
            end)
        end
    end

    local function StopHitboxExpander()
        Ex.Internal.HitboxDiscoverRunning = false
        for _, pl in ipairs(safeKeys(Ex.Internal.HitboxApplied)) do
            RestoreHitboxForPlayer(pl)
        end
        safeDisconnect(Ex.Internal.Conns.hitboxStep)
        Ex.Internal.Conns.hitboxStep = nil
        for _, conn in pairs(Ex.Internal.HitboxListeners) do
            safeDisconnect(conn)
        end
        Ex.Internal.HitboxListeners = {}
        Ex.Internal.HitboxWriting   = {}
    end

    --// =======================================================================
    --// BACKTRACK (unchanged — works)
    --// =======================================================================
    local BT_HISTORY_MAX = 64

    local function MakeGhostPart(srcPart, baseTransparency, style, forceColor)
        local clone
        local ok = pcall(function() clone = srcPart:Clone() end)
        if not ok or not clone then
            clone = Instance.new("Part")
            clone.Size = srcPart.Size
            clone.Color = srcPart.Color
            clone.Material = srcPart.Material
            clone.Name = srcPart.Name
        end
        for _, child in ipairs(clone:GetDescendants()) do
            if child:IsA("Script") or child:IsA("LocalScript")
               or child:IsA("Sound")
               or child:IsA("ParticleEmitter") or child:IsA("Trail") or child:IsA("Beam")
               or child:IsA("Attachment") or child:IsA("Motor6D")
               or child:IsA("Weld") or child:IsA("WeldConstraint")
               or child:IsA("HingeConstraint") or child:IsA("BallSocketConstraint")
               or child:IsA("Constraint") or child:IsA("Humanoid")
               or child:IsA("ClickDetector") or child:IsA("ProximityPrompt") then
                pcall(function() child:Destroy() end)
            end
        end
        local origT = clone.Transparency
        pcall(function() clone:SetAttribute("AirHub_OrigTransparency", origT) end)
        if style == "ForceField" then
            clone.Material     = Enum.Material.ForceField
            clone.Color        = forceColor or Color3.fromRGB(255, 80, 80)
            clone.Transparency = math.clamp(baseTransparency, 0, 1)
        else
            clone.Transparency = math.clamp(origT + baseTransparency * (1 - origT), 0, 1)
        end
        clone.Anchored     = true
        clone.CanCollide   = false
        clone.CanTouch     = false
        clone.CanQuery     = true
        clone.Massless     = true
        clone.CastShadow   = false
        clone.LocalTransparencyModifier = 0
        return clone
    end

    local function BuildGhost(player)
        local char = player.Character
        if not char then return nil, nil end
        local realRoot = char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart
        if not realRoot then return nil, nil end
        local style = Ex.Settings.BacktrackGhostStyle or "Clone"
        local baseT = Ex.Settings.BacktrackGhostTransparency or 0.35
        local boxColor = Ex.Settings.BacktrackBoxColor or Color3.fromRGB(255, 80, 80)
        local ghost = Instance.new("Model")
        ghost.Name = "AirHub_Ghost_" .. player.Name
        local offsets = {}
        local rootInv = realRoot.CFrame:Inverse()
        for _, obj in ipairs(char:GetDescendants()) do
            if obj:IsA("BasePart") and obj ~= realRoot then
                local clone = MakeGhostPart(obj, baseT, style, boxColor)
                clone.CFrame = obj.CFrame
                clone.Parent = ghost
                offsets[clone] = rootInv * obj.CFrame
            end
        end
        local rootClone = MakeGhostPart(realRoot, baseT, style, boxColor)
        rootClone.Name = "HumanoidRootPart"
        rootClone.Transparency = 1
        rootClone.CFrame = realRoot.CFrame
        rootClone.Parent = ghost
        offsets[rootClone] = CFrame.new()
        local hum = Instance.new("Humanoid")
        hum.MaxHealth = 100
        hum.Health = 100
        hum.PlatformStand = true
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end)
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false) end)
        hum.Parent = ghost
        local pv = Instance.new("ObjectValue")
        pv.Name = "Player"
        pv.Value = player
        pv.Parent = ghost
        pcall(function()
            ghost:SetAttribute("AirHub_Ghost", true)
            ghost:SetAttribute("AirHub_OwnerUserId", player.UserId)
            ghost:SetAttribute("AirHubInternal", true)
        end)
        ghost.PrimaryPart = rootClone
        ghost.Parent = workspace
        return ghost, offsets
    end

    local function ClearGhost(player)
        local ghost = Ex.Internal.BacktrackGhosts[player]
        if ghost and ghost.Parent then
            pcall(function() ghost:Destroy() end)
        end
        Ex.Internal.BacktrackGhosts[player]   = nil
        Ex.Internal.BacktrackGhostData[player] = nil
    end
    local function ClearAllGhosts()
        for _, pl in ipairs(safeKeys(Ex.Internal.BacktrackGhosts)) do
            ClearGhost(pl)
        end
        Ex.Internal.BacktrackGhosts   = {}
        Ex.Internal.BacktrackGhostData = {}
    end

    local function UpdateGhostPosition(player, rootCFrame)
        local ghost = Ex.Internal.BacktrackGhosts[player]
        local data  = Ex.Internal.BacktrackGhostData[player]
        if not ghost or not ghost.Parent or not data then return end
        for clone, offset in pairs(data.offsets) do
            if clone.Parent then
                pcall(function() clone.CFrame = rootCFrame * offset end)
            end
        end
    end

    local function RefreshGhostStyle(player)
        local ghost = Ex.Internal.BacktrackGhosts[player]
        if not ghost or not ghost.Parent then return end
        local style = Ex.Settings.BacktrackGhostStyle or "Clone"
        local baseT = Ex.Settings.BacktrackGhostTransparency or 0.35
        local boxColor = Ex.Settings.BacktrackBoxColor or Color3.fromRGB(255, 80, 80)
        for _, part in ipairs(ghost:GetDescendants()) do
            if part:IsA("BasePart") then
                if part.Name == "HumanoidRootPart" then
                    part.Transparency = 1
                elseif style == "ForceField" then
                    part.Material = Enum.Material.ForceField
                    part.Color = boxColor
                    part.Transparency = math.clamp(baseT, 0, 1)
                else
                    local orig = part:GetAttribute("AirHub_OrigTransparency") or 0
                    if part.Material == Enum.Material.ForceField then
                        part.Material = Enum.Material.Plastic
                    end
                    part.Transparency = math.clamp(orig + baseT * (1 - orig), 0, 1)
                end
                pcall(function() part:SetAttribute("AirHubInternal", true) end)
            end
        end
    end

    local function ResolveGhostToReal(v)
        if typeof(v) ~= "Instance" then return nil end
        local cursor = v
        local ghostModel = nil
        while cursor do
            if cursor:GetAttribute("AirHub_Ghost") then
                ghostModel = cursor
                break
            end
            cursor = cursor.Parent
        end
        if not ghostModel then return nil end
        local ownerPlayer = nil
        local pv = ghostModel:FindFirstChild("Player")
        if pv and pv.Value then
            ownerPlayer = pv.Value
        else
            local uid = ghostModel:GetAttribute("AirHub_OwnerUserId")
            if uid then ownerPlayer = Players:GetPlayerByUserId(uid) end
        end
        if not ownerPlayer or not ownerPlayer.Character then return nil end
        if v == ghostModel then return ownerPlayer.Character end
        local realChar = ownerPlayer.Character
        local real = realChar:FindFirstChild(v.Name)
        return real or realChar
    end

    local function StartGhostFireSwap()
        if Ex.Internal.GhostSwapHooked then return end
        local hookf     = getExec("hookmetamethod")
        local getMethod = getExec("getnamecallmethod")
        local newc      = getExec("newcclosure")
        local checkC    = getExec("checkcaller")
        if not hookf or not getMethod or not newc then
            warn("[AirHub] Backtrack: no hookmetamethod/newcclosure — intercept off")
            return
        end
        local mt = getrawmetatable and getrawmetatable(game)
        local realNamecall = mt and mt.__namecall or nil
        if type(realNamecall) ~= "function" then
            warn("[AirHub] Backtrack: cannot capture __namecall")
            return
        end
        Ex.Internal.GhostSwapOriginal = realNamecall
        local hooked = newc(function(self, ...)
            if H.ShuttingDown then return realNamecall(self, ...) end
            if getMethod() == "FireServer" and not (checkC and checkC()) then
                if next(Ex.Internal.BacktrackGhosts) then
                    local args = table.pack(...)
                    local swapped = false
                    for i = 1, args.n do
                        local v = args[i]
                        if typeof(v) == "Instance" then
                            local real = ResolveGhostToReal(v)
                            if real then args[i] = real; swapped = true end
                        end
                    end
                    if swapped then
                        return realNamecall(self, table.unpack(args, 1, args.n))
                    end
                end
            end
            return realNamecall(self, ...)
        end)
        local ok = pcall(function() hookf(game, "__namecall", hooked) end)
        if not ok then
            warn("[AirHub] Backtrack: hookmetamethod failed")
            Ex.Internal.GhostSwapOriginal = nil
            return
        end
        Ex.Internal.GhostSwapHooked = true
    end

    local function StopGhostFireSwap()
        if not Ex.Internal.GhostSwapHooked then return end
        local hookf = getExec("hookmetamethod")
        if hookf and Ex.Internal.GhostSwapOriginal then
            pcall(function() hookf(game, "__namecall", Ex.Internal.GhostSwapOriginal) end)
        end
        Ex.Internal.GhostSwapHooked  = false
        Ex.Internal.GhostSwapOriginal = nil
    end

    local function ClearBacktrackBox(player)
        local box = Ex.Internal.BacktrackBoxes[player]
        if box and box.Parent then pcall(function() box:Destroy() end) end
        Ex.Internal.BacktrackBoxes[player] = nil
    end
    local function ClearAllBacktrackBoxes()
        for _, pl in ipairs(safeKeys(Ex.Internal.BacktrackBoxes)) do
            ClearBacktrackBox(pl)
        end
        Ex.Internal.BacktrackBoxes = {}
    end

    local function SampleHistory(hist, targetTime)
        if not hist or #hist == 0 then return nil end
        if targetTime <= hist[1].time then return hist[1] end
        if targetTime >= hist[#hist].time then return hist[#hist] end
        local lo, hi = 1, #hist
        while lo < hi - 1 do
            local mid = (lo + hi) // 2
            if hist[mid].time <= targetTime then lo = mid else hi = mid end
        end
        local a, b = hist[lo], hist[hi]
        local span = b.time - a.time
        if span <= 0 then return b end
        local t = (targetTime - a.time) / span
        return {
            cframe = a.cframe:Lerp(b.cframe, t),
            time   = targetTime,
            speed  = a.speed + (b.speed - a.speed) * t,
        }
    end

    local function FindHistoryEntry(player, ms)
        if not player then return nil end
        local hist = Ex.Internal.BacktrackHistory[player]
        if not hist or #hist == 0 then return nil end
        local targetTime = os.clock() - ((ms or Ex.Settings.BacktrackTime) / 1000)
        return SampleHistory(hist, targetTime)
    end

    local function GetBacktrackCFrame(player, ms)
        local entry = FindHistoryEntry(player, ms)
        if entry then return entry.cframe end
        return nil
    end

    local function HookCharacterForPlayer(player)
        if Ex.Internal.BacktrackCharConns[player] then return end
        Ex.Internal.BacktrackCharConns[player] = player.CharacterAdded:Connect(function()
            if H.ShuttingDown then return end
            task.wait(0.3)
            if not Ex.Settings.BacktrackEnabled then return end
            ClearGhost(player)
            if Ex.Settings.BacktrackVisualize then
                local ghost, offsets = BuildGhost(player)
                if ghost then
                    Ex.Internal.BacktrackGhosts[player]    = ghost
                    Ex.Internal.BacktrackGhostData[player] = { offsets = offsets }
                end
            end
        end)
    end
    local function UnhookCharacterForPlayer(player)
        safeDisconnect(Ex.Internal.BacktrackCharConns[player])
        Ex.Internal.BacktrackCharConns[player] = nil
    end

    local function StartBacktrack()
        if Ex.Internal.Conns.bt then return end
        if Ex.Settings.BacktrackInterceptShots then
            StartGhostFireSwap()
        end
        Ex.Internal.Conns.bt = RunService.Heartbeat:Connect(function()
            if H.ShuttingDown or not Ex.Settings.BacktrackEnabled then return end
            local now = os.clock()
            local keep = (Ex.Settings.BacktrackTime / 1000) + 0.3
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl ~= LocalPlayer then
                    HookCharacterForPlayer(pl)
                    local char = pl.Character
                    if char then
                        local hrp = char:FindFirstChild("HumanoidRootPart")
                        if hrp then
                            local hist = Ex.Internal.BacktrackHistory[pl]
                            if not hist then
                                hist = {}
                                Ex.Internal.BacktrackHistory[pl] = hist
                            end
                            local vel = 0
                            pcall(function()
                                local v = hrp.AssemblyLinearVelocity or hrp.Velocity
                                vel = v.Magnitude
                            end)
                            hist[#hist + 1] = { cframe = hrp.CFrame, time = now, speed = vel }
                            while #hist > 0 and (now - hist[1].time) > keep do
                                table.remove(hist, 1)
                            end
                            if #hist > BT_HISTORY_MAX then
                                local drop = #hist - BT_HISTORY_MAX
                                for _ = 1, drop do table.remove(hist, 1) end
                            end
                        end
                    end
                end
            end
            for _, pl in ipairs(safeKeys(Ex.Internal.BacktrackHistory)) do
                if not pl.Parent then
                    Ex.Internal.BacktrackHistory[pl] = nil
                    UnhookCharacterForPlayer(pl)
                    ClearGhost(pl)
                    ClearBacktrackBox(pl)
                end
            end
            if Ex.Settings.BacktrackVisualize then
                for _, pl in ipairs(Players:GetPlayers()) do
                    if pl ~= LocalPlayer then
                        local char = pl.Character
                        local needsGhost = char and char:FindFirstChild("HumanoidRootPart")
                        if needsGhost then
                            local ghost = Ex.Internal.BacktrackGhosts[pl]
                            if not ghost or not ghost.Parent then
                                local newGhost, offsets = BuildGhost(pl)
                                if newGhost then
                                    Ex.Internal.BacktrackGhosts[pl]    = newGhost
                                    Ex.Internal.BacktrackGhostData[pl] = { offsets = offsets }
                                    ghost = newGhost
                                end
                            end
                            local cf = GetBacktrackCFrame(pl, Ex.Settings.BacktrackTime)
                            if cf and ghost and ghost.Parent then
                                UpdateGhostPosition(pl, cf)
                            elseif ghost then
                                ClearGhost(pl)
                            end
                        else
                            ClearGhost(pl)
                        end
                    end
                end
            else
                ClearAllGhosts()
            end
        end)
    end

    local function StopBacktrack()
        safeDisconnect(Ex.Internal.Conns.bt)
        Ex.Internal.Conns.bt = nil
        StopGhostFireSwap()
        ClearAllGhosts()
        ClearAllBacktrackBoxes()
        Ex.Internal.BacktrackHistory = {}
        for _, pl in ipairs(safeKeys(Ex.Internal.BacktrackCharConns)) do
            UnhookCharacterForPlayer(pl)
        end
        Ex.Internal.BacktrackCharConns = {}
    end

    Ex.Functions.GetBacktrackCFrame = function(player, ms)
        return GetBacktrackCFrame(player, ms)
    end
    Ex.Functions.GetBacktrackPosition = function(player, ms)
        local cf = GetBacktrackCFrame(player, ms)
        if cf then return cf.Position end
        return nil
    end
    Ex.Functions.GetBacktrackCFrameSmart = function(player, ms, hitboxSize)
        ms = ms or Ex.Settings.BacktrackTime
        hitboxSize = hitboxSize or 2
        local entry = FindHistoryEntry(player, ms)
        if not entry then return nil end
        if not Ex.Settings.BacktrackSmart then return entry.cframe end
        local speed = entry.speed or 0
        local maxTravel = speed * (ms / 1000)
        if maxTravel > hitboxSize * 2.5 then return nil end
        return entry.cframe
    end
    Ex.Functions.SetBacktrackTime = function(ms)
        ms = math.clamp(tonumber(ms) or 150, 50, 500)
        Ex.Settings.BacktrackTime = ms
    end
    Ex.Functions.SetBacktrackEnabled = function(state)
        state = state and true or false
        Ex.Settings.BacktrackEnabled = state
        if state then
            StartBacktrack()
            -- NOTE: auto-enable of FakeLag REMOVED — was the #1 cause of "everything broken"
        else
            StopBacktrack()
        end
    end
    Ex.Functions.RefreshBacktrackVisuals = function()
        for _, pl in ipairs(safeKeys(Ex.Internal.BacktrackGhosts)) do
            RefreshGhostStyle(pl)
        end
    end

    --// =======================================================================
    --// FAKELAG (REWRITTEN — safe by default)
    --// =======================================================================
    -- Hardcoded blacklist: never delay these remotes. Game-critical infrastructure.
    local FAKE_LAG_BLACKLIST = {
        -- Chat
        "chat", "say", "message", "whisper", "teamchat",
        -- Commerce
        "buy", "shop", "purchase", "sell", "trade", "currency",
        -- Reporting / moderation
        "report", "anticheat", "kick", "ban", "security", "moderation",
        -- Teleport / server
        "teleport", "server", "respawn",
        -- Inventory / equip
        "equip", "inventory", "loadout",
        -- Vote / poll
        "vote", "poll",
    }
    -- Movement heuristic: only delay remotes containing these substrings.
    local FAKE_LAG_MOVEMENT = {
        "position", "move", "input", "update", "state",
        "walk", "run", "jump", "velocity", "physics",
        "character", "player", "sync", "movement",
    }

    local function GetCustomList()
        local out = {}
        local raw = tostring(Ex.Settings.FakeLagCustomList or "")
        for token in string.gmatch(raw, "[^,]+") do
            token = token:gsub("^%s+", ""):gsub("%s+$", ""):lower()
            if token ~= "" then out[#out + 1] = token end
        end
        return out
    end

    local function ShouldDelayFakeLag(self)
        local ok, name = pcall(function() return tostring(self.Name or "") end)
        if not ok then return false end
        local lower = name:lower()
        -- Blacklist always wins
        for _, pat in ipairs(FAKE_LAG_BLACKLIST) do
            if lower:find(pat, 1, true) then return false end
        end
        local mode = Ex.Settings.FakeLagMode or "Movement"
        if mode == "All" then
            return true
        elseif mode == "Movement" then
            for _, pat in ipairs(FAKE_LAG_MOVEMENT) do
                if lower:find(pat, 1, true) then return true end
            end
            return false
        elseif mode == "Custom" then
            for _, pat in ipairs(GetCustomList()) do
                if lower:find(pat, 1, true) then return true end
            end
            return false
        end
        return false
    end

    local function IsRateLimited(self, now)
        local ok, name = pcall(function() return tostring(self.Name or "") end)
        if not ok then return false end
        local rl = tonumber(Ex.Settings.FakeLagRateLimit) or 0.02
        local last = Ex.Internal.FakeLagLastSent[name]
        if last and (now - last) < rl then return true end
        Ex.Internal.FakeLagLastSent[name] = now
        return false
    end

    -- Flush queue gradually so we don't trigger server rate-limits
    local function FlushFakeLagQueue()
        if Ex.Internal.FakeLagFlushing then return end
        Ex.Internal.FakeLagFlushing = true
        local q = Ex.Internal.FakeLagQueue
        local orig = Ex.Internal.FakeLagOriginal
        local head = Ex.Internal.FakeLagHead
        local count = 0
        for i = head, #q do
            local item = q[i]
            if item then
                pcall(function()
                    if orig then
                        orig(item.self, table.unpack(item.args, 1, item.args.n))
                    elseif item.self and type(item.self.FireServer) == "function" then
                        item.self:FireServer(table.unpack(item.args, 1, item.args.n))
                    end
                end)
                count = count + 1
                if count % 5 == 0 then
                    task.wait(0.005) -- 5ms between batches
                end
            end
        end
        Ex.Internal.FakeLagQueue = {}
        Ex.Internal.FakeLagHead  = 1
        Ex.Internal.FakeLagFlushing = false
    end

    StartFakeLag = function()
        if Ex.Internal.FakeLagHooked then return end
        local hookf     = getExec("hookmetamethod")
        local getMethod = getExec("getnamecallmethod")
        local newc      = getExec("newcclosure")
        local checkC    = getExec("checkcaller")
        if not hookf or not getMethod or not newc then
            warn("[AirHub] FakeLag: executor lacks hookmetamethod/newcclosure")
            Ex.Settings.FakeLagEnabled = false
            return
        end
        local mt = getrawmetatable and getrawmetatable(game)
        local realNamecall = mt and mt.__namecall or nil
        if type(realNamecall) ~= "function" then
            warn("[AirHub] FakeLag: cannot capture __namecall")
            Ex.Settings.FakeLagEnabled = false
            return
        end
        Ex.Internal.FakeLagOriginal = realNamecall

        local hooked = newc(function(self, ...)
            if H.ShuttingDown then return realNamecall(self, ...) end
            if getMethod() == "FireServer" and not (checkC and checkC()) then
                -- FIX 1: only-alive check
                if Ex.Settings.FakeLagOnlyAlive and not IsLocalPlayerAlive() then
                    return realNamecall(self, ...)
                end
                -- FIX 2: filter by name (Movement only by default)
                if not ShouldDelayFakeLag(self) then
                    return realNamecall(self, ...)
                end
                -- FIX 3: rate-limit per remote — hot remotes pass through
                local now = os.clock()
                if IsRateLimited(self, now) then
                    return realNamecall(self, ...)
                end
                -- FIX 4: queue length cap
                local q = Ex.Internal.FakeLagQueue
                local qlen = #q - (Ex.Internal.FakeLagHead - 1)
                local cap = tonumber(Ex.Settings.FakeLagMaxQueue) or 50
                if qlen >= cap then
                    FlushFakeLagQueue()
                end
                local due = now + (Ex.Settings.FakeLagTime / 1000)
                Ex.Internal.FakeLagSeq = Ex.Internal.FakeLagSeq + 1
                q[#q + 1] = {
                    self = self,
                    args = table.pack(...),
                    due  = due,
                    seq  = Ex.Internal.FakeLagSeq,
                }
                return
            end
            return realNamecall(self, ...)
        end)

        local ok = pcall(function() hookf(game, "__namecall", hooked) end)
        if not ok then
            warn("[AirHub] FakeLag: hookmetamethod failed")
            Ex.Internal.FakeLagOriginal = nil
            Ex.Settings.FakeLagEnabled = false
            return
        end
        Ex.Internal.FakeLagHooked = true

        Ex.Internal.FakeLagFlushConn = RunService.Heartbeat:Connect(function()
            if H.ShuttingDown then return end
            if Ex.Settings.FakeLagOnlyAlive and not IsLocalPlayerAlive() then
                if #Ex.Internal.FakeLagQueue > 0 then FlushFakeLagQueue() end
                return
            end
            local now = os.clock()
            local q = Ex.Internal.FakeLagQueue
            local head = Ex.Internal.FakeLagHead
            local orig = Ex.Internal.FakeLagOriginal
            local flushed = 0
            while head <= #q do
                local item = q[head]
                if item and item.due <= now then
                    pcall(function()
                        if orig then
                            orig(item.self, table.unpack(item.args, 1, item.args.n))
                        elseif item.self and type(item.self.FireServer) == "function" then
                            item.self:FireServer(table.unpack(item.args, 1, item.args.n))
                        end
                    end)
                    q[head] = nil
                    head = head + 1
                    flushed = flushed + 1
                    -- don't flush more than 20 per heartbeat (server protection)
                    if flushed >= 20 then break end
                else
                    break
                end
            end
            Ex.Internal.FakeLagHead = head
            if head > 32 and head > #q * 0.5 then
                local compact = {}
                for i = head, #q do compact[#compact + 1] = q[i] end
                Ex.Internal.FakeLagQueue = compact
                Ex.Internal.FakeLagHead  = 1
            end
        end)

        -- Hook death → flush safely
        if LocalPlayer.Character then
            local hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            if hum then
                Ex.Internal.Conns.fakelagDied = hum.Died:Connect(function()
                    FlushFakeLagQueue()
                end)
            end
        end
        -- Watch for respawn
        Ex.Internal.Conns.fakelagChar = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.5)
            if H.ShuttingDown then return end
            FlushFakeLagQueue()
            if Ex.Settings.FakeLagEnabled then
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum then
                    safeDisconnect(Ex.Internal.Conns.fakelagDied)
                    Ex.Internal.Conns.fakelagDied = hum.Died:Connect(function()
                        FlushFakeLagQueue()
                    end)
                end
            end
        end)
    end

    StopFakeLag = function()
        -- Restore hook FIRST so flush uses real path
        local hookf = getExec("hookmetamethod")
        if hookf and Ex.Internal.FakeLagOriginal and Ex.Internal.FakeLagHooked then
            pcall(function() hookf(game, "__namecall", Ex.Internal.FakeLagOriginal) end)
        end
        Ex.Internal.FakeLagHooked = false
        -- Then flush queue safely
        FlushFakeLagQueue()
        Ex.Internal.FakeLagQueue = {}
        Ex.Internal.FakeLagHead  = 1
        Ex.Internal.FakeLagLastSent = {}
        safeDisconnect(Ex.Internal.FakeLagFlushConn)
        Ex.Internal.FakeLagFlushConn = nil
        safeDisconnect(Ex.Internal.Conns.fakelagDied)
        Ex.Internal.Conns.fakelagDied = nil
        safeDisconnect(Ex.Internal.Conns.fakelagChar)
        Ex.Internal.Conns.fakelagChar = nil
        Ex.Internal.FakeLagOriginal = nil
    end

    Ex.Functions.SetFakeLagEnabled = function(state)
        state = state and true or false
        Ex.Settings.FakeLagEnabled = state
        if state then StartFakeLag() else StopFakeLag() end
    end

    --// =======================================================================
    --// WORLD
    --// =======================================================================
    local function applySeeThroughPart(obj)
        if obj:IsA("BasePart") and not isCharacterPart(obj) then
            if isAirHubInternal(obj) then return end
            local origT = obj.Transparency
            if origT >= 0.5 then return end
            if Ex.Internal.SavedWorldParts[obj] == nil then
                Ex.Internal.SavedWorldParts[obj] = obj.LocalTransparencyModifier
            end
            pcall(function() obj.LocalTransparencyModifier = 0.7 end)
        end
    end

    local function StartSeeThroughWalls()
        for _, obj in ipairs(workspace:GetDescendants()) do
            applySeeThroughPart(obj)
        end
        if not Ex.Internal.Conns.stw then
            Ex.Internal.Conns.stw = workspace.DescendantAdded:Connect(function(obj)
                if H.ShuttingDown then return end
                if Ex.Settings.SeeThroughWalls then
                    applySeeThroughPart(obj)
                end
            end)
        end
    end
    local function StopSeeThroughWalls()
        for obj, orig in pairs(Ex.Internal.SavedWorldParts) do
            pcall(function() obj.LocalTransparencyModifier = orig or 0 end)
        end
        Ex.Internal.SavedWorldParts = {}
        safeDisconnect(Ex.Internal.Conns.stw)
        Ex.Internal.Conns.stw = nil
    end

    local function StartFullbright()
        if not Ex.Internal.FullbrightSaved then
            Ex.Internal.FullbrightOriginals = {
                Ambient        = Lighting.Ambient,
                OutdoorAmbient = Lighting.OutdoorAmbient,
                Brightness     = Lighting.Brightness,
                GlobalShadows  = Lighting.GlobalShadows,
            }
            Ex.Internal.FullbrightSaved = true
        end
        pcall(function()
            Lighting.Ambient        = Color3.fromRGB(255, 255, 255)
            Lighting.OutdoorAmbient = Color3.fromRGB(255, 255, 255)
            Lighting.Brightness     = Ex.Settings.FullbrightBrightness
            Lighting.GlobalShadows  = false
        end)
    end
    local function StopFullbright()
        if Ex.Internal.FullbrightOriginals then
            local o = Ex.Internal.FullbrightOriginals
            pcall(function()
                Lighting.Ambient        = o.Ambient
                Lighting.OutdoorAmbient = o.OutdoorAmbient
                Lighting.Brightness     = o.Brightness
                Lighting.GlobalShadows  = o.GlobalShadows
            end)
        end
    end

    local function StartRemoveFog()
        if not Ex.Internal.FogSaved then
            local atm = Lighting:FindFirstChildOfClass("Atmosphere")
            Ex.Internal.OriginalFog = {
                FogEnd = Lighting.FogEnd,
                FogStart = Lighting.FogStart,
                FogColor = Lighting.FogColor,
                Atmosphere = atm,
                AtmosphereDensity = atm and atm.Density or nil,
            }
            Ex.Internal.FogSaved = true
        end
        pcall(function()
            Lighting.FogEnd   = 1e9
            Lighting.FogStart = 0
            local atm = Lighting:FindFirstChildOfClass("Atmosphere")
            if atm then atm.Density = 0 end
        end)
    end
    local function StopRemoveFog()
        if Ex.Internal.OriginalFog then
            local o = Ex.Internal.OriginalFog
            pcall(function()
                Lighting.FogEnd   = o.FogEnd
                Lighting.FogStart = o.FogStart
                Lighting.FogColor = o.FogColor
                if o.Atmosphere and o.Atmosphere.Parent and o.AtmosphereDensity then
                    o.Atmosphere.Density = o.AtmosphereDensity
                end
            end)
        end
    end

    local function StartRemoveSkybox()
        local sky = Lighting:FindFirstChildOfClass("Sky")
        if sky then
            if not Ex.Internal.SkyboxSaved then
                Ex.Internal.OriginalSky = sky
                Ex.Internal.SkyboxSaved = true
            end
            pcall(function() sky.Parent = nil end)
        end
    end
    local function StopRemoveSkybox()
        if Ex.Internal.OriginalSky and Ex.Internal.OriginalSky.Parent == nil then
            pcall(function() Ex.Internal.OriginalSky.Parent = Lighting end)
        end
    end

    --// =======================================================================
