    --// =======================================================================
    Ex.Functions.TeleportToPlayer = function(nameQuery)
        if not nameQuery or nameQuery == "" then return end
        local q = string.lower(nameQuery)
        local target
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and string.find(string.lower(p.Name), q, 1, true) then
                target = p; break
            end
        end
        if not target or not target.Character then
            if Util.AddLog then
                Util.AddLog("Teleport: player not found", Color3.fromRGB(255, 100, 100))
            end
            return
        end
        local myChar = LocalPlayer.Character
        local myHrp  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local tgtHrp = target.Character:FindFirstChild("HumanoidRootPart")
        if myHrp and tgtHrp then
            myHrp.CFrame = tgtHrp.CFrame * CFrame.new(0, 0, 3)
            if Util.AddLog then
                Util.AddLog("Teleported to " .. target.Name, Color3.fromRGB(120, 220, 120))
            end
        end
    end

    Ex.Functions.Rejoin = function()
        pcall(function()
            TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
        end)
    end

    local function getRequestFn()
        if type(syn) == "table" and type(syn.request) == "function" then return syn.request end
        if type(request) == "function" then return request end
        if type(http_request) == "function" then return http_request end
        return nil
    end

    Ex.Functions.ServerHop = function()
        local req = getRequestFn()
        if not req then
            warn("[AirHub] Server hop: no HTTP method available"); return
        end
        pcall(function()
            local url = string.format(
                "https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100",
                game.PlaceId
            )
            local res = req({ Url = url, Method = "GET" })
            if not res or type(res.StatusCode) ~= "number" or res.StatusCode ~= 200 then return end
            local okDec, data = pcall(function() return HttpService:JSONDecode(res.Body) end)
            if not okDec or type(data) ~= "table" or type(data.data) ~= "table" then return end
            local candidates = {}
            for _, srv in ipairs(data.data) do
                if srv.playing and srv.maxPlayers
                   and srv.playing < srv.maxPlayers
                   and srv.id ~= game.JobId then
                    candidates[#candidates + 1] = srv.id
                end
            end
            if #candidates > 0 then
                local pick = candidates[math.random(1, #candidates)]
                TeleportService:TeleportToPlaceInstance(game.PlaceId, pick, LocalPlayer)
            end
        end)
    end

    Ex.Functions.CopyJobId = function()
        local sc = rawget(_G, "setclipboard") or rawget(_G, "toclipboard")
        if type(sc) == "function" then pcall(sc, game.JobId) end
    end
    Ex.Functions.CopyJobID = Ex.Functions.CopyJobId

