-- Localize helper (T from airhubUI if present)
local function T(key, ...)
    local UI = getgenv().airhubUI
    if UI and UI.T then
        local ok, res = pcall(UI.T, key, ...)
        if ok and type(res) == "string" then return res end
    end
    return key
end

