local cfgHintSec = SettingsTab:CreateSection({ Name = "set_sec_cfg", Side = "Right" })
cfgHintSec:AddLabel({ Text = "set_cfg_hint1" })
cfgHintSec:AddLabel({ Text = "set_cfg_hint2",
